class OsmParkingMapCardV070 extends HTMLElement {
  static getStubConfig() {
    return {
      entity: 'sensor.parking_suggestions',
      height: 430,
      show_list: true,
    };
  }

  setConfig(config) {
    if (!config || !config.entity) throw new Error('Please define an entity');
    this.config = {
      title: null,
      height: 430,
      show_list: true,
      show_destination: true,
      show_zones: true,
      show_price: true,
      map_style: 'https://tiles.openfreemap.org/styles/liberty',
      ...config,
    };
    this._lastSignature = null;
    this._map = null;
    this._markers = [];
    this._renderShell();
  }

  set hass(hass) {
    this._hass = hass;
    const state = hass?.states?.[this.config.entity];
    if (!state) {
      this._els.title.textContent = this.config.title || this._t('title');
      this._setContentVisible(false);
      this._showStatus({
        title: this._st('entityMissingTitle'),
        message: this._st('entityMissingBody'),
        details: this.config.entity,
        actions: [
          { label: this._st('settings'), handler: () => this._openSettings() },
        ],
      });
      return;
    }

    const a = state.attributes || {};
    if (
      !('destination_entity' in a)
      && !('destination_latitude' in a)
      && !Array.isArray(a.suggestions)
    ) {
      this._els.title.textContent = this.config.title || this._t('title');
      this._setContentVisible(false);
      this._showStatus({
        title: this._st('wrongEntityTitle'),
        message: this._st('wrongEntityBody'),
        details: this.config.entity,
        actions: [
          { label: this._st('settings'), handler: () => this._openSettings() },
        ],
      });
      return;
    }

    const signature = JSON.stringify({
      state: state.state,
      language: hass?.language,
      destination_entity: a.destination_entity,
      destination_name: a.destination_name,
      destination_latitude: a.destination_latitude,
      destination_longitude: a.destination_longitude,
      error: a.error,
      error_code: a.error_code,
      auto_retry: a.auto_retry,
      retry_after_seconds: a.retry_after_seconds,
      partial_data: a.partial_data,
      provider_errors: a.provider_errors,
      providers_used: a.providers_used,
      realtime_result_count: a.realtime_result_count,
      live_refresh_seconds: a.live_refresh_seconds,
      suggestions: a.suggestions,
      parking_zones: a.parking_zones,
    });

    if (signature === this._lastSignature) return;
    this._lastSignature = signature;
    this._stateObj = state;
    void this._update();
  }

  getCardSize() {
    return 6;
  }

  _renderShell() {
    this.innerHTML = `
      <ha-card>
        <div class="header">
          <div>
            <div class="title"></div>
            <div class="subtitle"></div>
          </div>
          <div class="headright"><span class="version">v1.3.0</span><ha-icon icon="mdi:parking"></ha-icon></div>
        </div>
        <div class="status-panel" hidden>
          <div class="status-head">
            <ha-icon class="status-icon"></ha-icon>
            <div>
              <div class="status-title"></div>
              <div class="status-message"></div>
            </div>
          </div>
          <div class="status-actions"></div>
          <details class="status-details" hidden>
            <summary></summary>
            <pre></pre>
          </details>
        </div>
        <div class="map" style="height:${Number(this.config.height) || 430}px"></div>
        <div class="list" ${this.config.show_list === false ? 'hidden' : ''}></div>
      </ha-card>
      <style>
        ha-card { overflow:hidden; }
        .header { display:flex; justify-content:space-between; align-items:center; gap:12px; padding:16px 16px 12px; }
        .title { font-size:1.15rem; font-weight:600; color:var(--primary-text-color); }
        .subtitle { margin-top:4px; color:var(--secondary-text-color); font-size:.9rem; line-height:1.35; }
        .headright { display:flex; align-items:center; gap:8px; }
        .version { font-size:.68rem; color:var(--secondary-text-color); opacity:.72; }
        .header ha-icon { color:var(--state-icon-color); --mdc-icon-size:28px; flex:0 0 auto; }
        .map {
          width:100%;
          position:relative;
          overflow:hidden;
          contain:layout paint;
          isolation:isolate;
          background:var(--secondary-background-color);
        }
        /*
         * MapLibre's CDN stylesheet lives outside Home Assistant's shadow-DOM
         * boundaries, so its structural positioning rules are not guaranteed to
         * reach a custom card. Keep the critical layout rules local to the card.
         */
        .map.maplibregl-map { position:relative; overflow:hidden; -webkit-tap-highlight-color:rgb(0 0 0 / 0%); }
        .map .maplibregl-canvas-container { position:absolute; inset:0; width:100%; height:100%; }
        .map .maplibregl-canvas { position:absolute; left:0; top:0; display:block; }
        .map .maplibregl-marker {
          position:absolute;
          left:0;
          top:0;
          will-change:transform;
          z-index:2;
        }
        .map .maplibregl-popup {
          position:absolute;
          left:0;
          top:0;
          display:flex;
          will-change:transform;
          pointer-events:none;
          z-index:3;
        }
        .map .maplibregl-popup-content { position:relative; pointer-events:auto; }
        .map .maplibregl-popup-close-button { position:absolute; right:0; top:0; border:0; background:transparent; cursor:pointer; }
        .map .maplibregl-control-container { position:absolute; inset:0; pointer-events:none; z-index:4; }
        .map .maplibregl-ctrl-top-left,
        .map .maplibregl-ctrl-top-right,
        .map .maplibregl-ctrl-bottom-left,
        .map .maplibregl-ctrl-bottom-right { position:absolute; pointer-events:none; z-index:4; }
        .map .maplibregl-ctrl-top-left { top:0; left:0; }
        .map .maplibregl-ctrl-top-right { top:0; right:0; }
        .map .maplibregl-ctrl-bottom-left { bottom:0; left:0; }
        .map .maplibregl-ctrl-bottom-right { right:0; bottom:0; }
        .map .maplibregl-ctrl { clear:both; pointer-events:auto; transform:translate(0); }
        .status-panel { margin:0 16px 16px; padding:14px; border-radius:12px; background:var(--secondary-background-color); border:1px solid var(--divider-color); color:var(--primary-text-color); }
        .status-panel.error { background:color-mix(in srgb,var(--error-color) 9%,var(--card-background-color)); border-color:color-mix(in srgb,var(--error-color) 35%,var(--divider-color)); }
        .status-panel.warning { background:color-mix(in srgb,#ff9800 9%,var(--card-background-color)); border-color:color-mix(in srgb,#ff9800 35%,var(--divider-color)); }
        .status-panel.info { background:color-mix(in srgb,var(--primary-color) 7%,var(--card-background-color)); border-color:color-mix(in srgb,var(--primary-color) 30%,var(--divider-color)); }
        .status-head { display:grid; grid-template-columns:auto 1fr; gap:10px; align-items:start; }
        .status-icon { --mdc-icon-size:24px; color:var(--secondary-text-color); }
        .status-panel.error .status-icon { color:var(--error-color); }
        .status-title { font-weight:700; line-height:1.35; }
        .status-message { margin-top:4px; color:var(--secondary-text-color); line-height:1.45; }
        .status-actions { display:flex; flex-wrap:wrap; gap:8px; margin-top:12px; }
        .status-button { border:0; border-radius:18px; padding:8px 13px; cursor:pointer; font:inherit; font-weight:600; color:var(--primary-text-color); background:var(--secondary-background-color); box-shadow:inset 0 0 0 1px var(--divider-color); }
        .status-button.primary { color:var(--text-primary-color,#fff); background:var(--primary-color); box-shadow:none; }
        .status-button:disabled { opacity:.55; cursor:default; }
        .status-details { margin-top:10px; color:var(--secondary-text-color); }
        .status-details summary { cursor:pointer; font-weight:600; }
        .status-details pre { white-space:pre-wrap; overflow-wrap:anywhere; font-size:.78rem; margin:8px 0 0; }
        .list { padding:8px 12px 12px; display:grid; gap:8px; }
        .parking-row { display:grid; grid-template-columns:auto 1fr auto; align-items:center; gap:10px; padding:10px; border-radius:12px; background:var(--secondary-background-color); cursor:pointer; }
        .parking-row:hover { filter:brightness(1.04); }
        .badge { min-width:34px; height:34px; border-radius:50%; display:grid; place-items:center; background:var(--primary-color); color:#fff; font-weight:700; }
        .row-title { font-weight:600; color:var(--primary-text-color); }
        .row-meta { margin-top:2px; color:var(--secondary-text-color); font-size:.84rem; }
        .row-source { margin-top:2px; color:var(--secondary-text-color); opacity:.78; font-size:.74rem; }
        .row-price { font-weight:600; white-space:nowrap; color:var(--primary-text-color); }
        .osm-dest-marker,.osm-park-marker { width:32px; height:32px; border-radius:50%; display:grid; place-items:center; border:3px solid #fff; box-shadow:0 1px 5px rgba(0,0,0,.45); color:#fff; font-weight:800; box-sizing:border-box; }
        .osm-dest-marker { background:#d32f2f; }
        .osm-park-marker { background:#1976d2; }
        .maplibregl-popup-content { background:var(--card-background-color,#fff); color:var(--primary-text-color,#111); border-radius:10px; padding:12px 14px; min-width:190px; }
        .maplibregl-popup-tip { border-top-color:var(--card-background-color,#fff) !important; }
        .maplibregl-popup-close-button { color:var(--primary-text-color,#111); font-size:20px; }
        .popup-title { font-weight:700; margin-bottom:6px; padding-right:12px; }
        .popup-line { margin:3px 0; }
        .popup-actions { display:flex; gap:12px; margin-top:9px; }
        .popup-actions a { color:var(--primary-color); text-decoration:none; font-weight:600; }
      </style>`;
    this._els = {
      title: this.querySelector('.title'),
      subtitle: this.querySelector('.subtitle'),
      map: this.querySelector('.map'),
      list: this.querySelector('.list'),
      status: this.querySelector('.status-panel'),
      statusIcon: this.querySelector('.status-icon'),
      statusTitle: this.querySelector('.status-title'),
      statusMessage: this.querySelector('.status-message'),
      statusActions: this.querySelector('.status-actions'),
      statusDetails: this.querySelector('.status-details'),
      statusDetailsSummary: this.querySelector('.status-details summary'),
      statusDetailsPre: this.querySelector('.status-details pre'),
    };
  }

  _providerTranslations() {
    const raw = String(this._hass?.language || 'en').replace('_', '-');
    if (OSM_PARKING_PROVIDER_I18N[raw]) return OSM_PARKING_PROVIDER_I18N[raw];
    const base = raw.split('-')[0];
    return OSM_PARKING_PROVIDER_I18N[base] || OSM_PARKING_PROVIDER_I18N.en;
  }

  _pt(key) {
    return this._providerTranslations()[key]
      ?? OSM_PARKING_PROVIDER_I18N.en[key]
      ?? key;
  }

  _qt(key) {
    const raw = String(this._hass?.language || 'en').replace('_', '-');
    const lang = OSM_PARKING_QUALITY_I18N[raw]
      || OSM_PARKING_QUALITY_I18N[raw.split('-')[0]]
      || OSM_PARKING_QUALITY_I18N.en;
    return lang[key] || OSM_PARKING_QUALITY_I18N.en[key] || key;
  }

  _zt(key) {
    const raw = String(this._hass?.language || 'en').replace('_', '-');
    const dict = OSM_PARKING_ZONE_I18N[raw]
      || OSM_PARKING_ZONE_I18N[raw.split('-')[0]]
      || OSM_PARKING_ZONE_I18N.en;
    return dict[key] || OSM_PARKING_ZONE_I18N.en[key] || key;
  }

  _availabilityText(suggestion) {
    const kind = suggestion.availability_kind || (suggestion.has_realtime_data ? 'live' : 'static');
    if (!['live', 'reported'].includes(kind) || suggestion.free_capacity == null) return '';
    const free = Number(suggestion.free_capacity);
    if (!Number.isFinite(free) || free < 0) return '';
    const capacity = suggestion.capacity == null ? NaN : Number(suggestion.capacity);
    if (Number.isFinite(capacity) && capacity >= free) {
      return `${Math.round(free)}/${Math.round(capacity)} ${this._pt('available')}`;
    }
    return `${Math.round(free)} ${this._pt('available')}`;
  }

  _estimatedTranslations() {
    const raw = String(this._hass?.language || 'en').replace('_', '-');
    if (OSM_PARKING_ESTIMATED_I18N[raw]) return OSM_PARKING_ESTIMATED_I18N[raw];
    const base = raw.split('-')[0];
    return OSM_PARKING_ESTIMATED_I18N[base] || OSM_PARKING_ESTIMATED_I18N.en;
  }

  _estimatedOccupancyText(suggestion) {
    if (suggestion.availability_kind && suggestion.availability_kind !== 'estimated') return '';
    let percent = suggestion.estimated_occupancy_percent == null ? NaN : Number(suggestion.estimated_occupancy_percent);
    if (!Number.isFinite(percent)) {
      const ratio = suggestion.estimated_occupancy_ratio == null ? NaN : Number(suggestion.estimated_occupancy_ratio);
      if (Number.isFinite(ratio)) percent = ratio * 100;
    }
    if (!Number.isFinite(percent)) return '';

    const translations = this._estimatedTranslations();
    const levelKey = String(suggestion.estimated_occupancy_level || '').toLowerCase();
    const level = translations[levelKey] || '';
    return `${Math.round(percent)}%${level ? ` · ${level}` : ''}`;
  }

  _formatProviderTime(value) {
    if (!value) return '';
    const parsed = new Date(value);
    if (Number.isNaN(parsed.getTime())) return String(value);
    try {
      return parsed.toLocaleString(this._hass?.language || undefined);
    } catch (_) {
      return String(value);
    }
  }

  _statusTranslations() {
    const raw = String(this._hass?.language || 'en').replace('_', '-');
    if (OSM_PARKING_STATUS_I18N[raw]) return OSM_PARKING_STATUS_I18N[raw];
    const base = raw.split('-')[0];
    return OSM_PARKING_STATUS_I18N[base] || OSM_PARKING_STATUS_I18N.en;
  }

  _st(key) {
    return this._statusTranslations()[key]
      ?? OSM_PARKING_STATUS_I18N.en[key]
      ?? key;
  }

  _showStatus({
    tone = 'error',
    icon = 'mdi:alert-circle-outline',
    title,
    message,
    details = '',
    actions = [],
  }) {
    if (!this._els) this._renderShell();
    const panel = this._els.status;
    panel.hidden = false;
    panel.className = `status-panel ${tone}`;
    this._els.statusIcon.setAttribute('icon', icon);
    this._els.statusTitle.textContent = title || '';
    this._els.statusMessage.textContent = message || '';
    this._els.statusActions.innerHTML = '';

    actions.forEach((action, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = `status-button${index === 0 ? ' primary' : ''}`;
      button.textContent = action.label;
      button.addEventListener('click', action.handler);
      this._els.statusActions.appendChild(button);
    });

    this._els.statusDetails.hidden = !details;
    this._els.statusDetailsSummary.textContent = this._st('technical');
    this._els.statusDetailsPre.textContent = details || '';
  }

  _hideStatus() {
    if (this._els) this._els.status.hidden = true;
  }

  _setContentVisible(visible) {
    if (!this._els) return;
    this._els.map.hidden = !visible;
    if (this.config.show_list !== false) this._els.list.hidden = !visible;
  }

  async _retryNow() {
    if (!this._hass || !this.config.entity) return;
    try {
      await this._hass.callService(
        'homeassistant',
        'update_entity',
        { entity_id: this.config.entity },
      );
    } catch (error) {
      this._showStatus({
        title: this._st('genericTitle'),
        message: this._st('genericBody'),
        details: error?.message || String(error),
        actions: [
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
        ],
      });
    }
  }

  _openSource(entityId) {
    if (!entityId) return;
    this.dispatchEvent(new CustomEvent('hass-more-info', {
      detail: { entityId },
      bubbles: true,
      composed: true,
    }));
  }

  _openSettings() {
    const path = '/config/integrations/integration/osm_parking';
    history.pushState(null, '', path);
    window.dispatchEvent(new Event('location-changed'));
  }

  _reportIssue() {
    window.open(
      'https://github.com/Chreece/HA-OSM-Parking/issues/new',
      '_blank',
      'noopener',
    );
  }

  _retryMessage(attributes) {
    const seconds = Number(attributes.retry_after_seconds);
    if (!attributes.auto_retry || !Number.isFinite(seconds) || seconds <= 0) {
      return this._st('noAction');
    }
    const minutes = Math.max(1, Math.round(seconds / 60));
    return this._st('autoRetry').replace('{minutes}', String(minutes));
  }

  _showBackendStatus(attributes) {
    const code = String(attributes.error_code || '');
    const source = attributes.destination_entity;
    const details = attributes.error || '';

    if (code === 'source_unavailable') {
      this._showStatus({
        tone: 'warning',
        icon: 'mdi:map-marker-alert-outline',
        title: this._st('sourceUnavailableTitle'),
        message: this._st('sourceUnavailableBody'),
        details,
        actions: [
          ...(source ? [{
            label: this._st('openSource'),
            handler: () => this._openSource(source),
          }] : []),
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
          { label: this._st('settings'), handler: () => this._openSettings() },
        ],
      });
      return true;
    }

    if (code === 'source_coordinates_missing') {
      this._showStatus({
        tone: 'warning',
        icon: 'mdi:crosshairs-question',
        title: this._st('sourceCoordsTitle'),
        message: this._st('sourceCoordsBody'),
        details,
        actions: [
          ...(source ? [{
            label: this._st('openSource'),
            handler: () => this._openSource(source),
          }] : []),
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
          { label: this._st('settings'), handler: () => this._openSettings() },
        ],
      });
      return true;
    }

    if (code === 'overpass_unavailable') {
      this._showStatus({
        tone: 'warning',
        icon: 'mdi:cloud-alert-outline',
        title: this._st('overpassTitle'),
        message: `${this._st('overpassBody')} ${this._retryMessage(attributes)}`,
        details,
        actions: [
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
        ],
      });
      return true;
    }

    if (code === 'overpass_rejected') {
      this._showStatus({
        tone: 'error',
        icon: 'mdi:cloud-remove-outline',
        title: this._st('overpassRejectedTitle'),
        message: this._st('overpassRejectedBody'),
        details,
        actions: [
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
          { label: this._st('reportIssue'), handler: () => this._reportIssue() },
        ],
      });
      return true;
    }

    if (attributes.status === 'error' || this._stateObj?.state === 'error') {
      this._showStatus({
        tone: 'error',
        icon: 'mdi:alert-circle-outline',
        title: this._st('genericTitle'),
        message: `${this._st('genericBody')} ${this._retryMessage(attributes)}`,
        details,
        actions: [
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
          { label: this._st('reportIssue'), handler: () => this._reportIssue() },
        ],
      });
      return true;
    }

    if (attributes.partial_data) {
      const providerErrors = attributes.provider_errors || {};
      const detailsText = [
        attributes.error || '',
        ...Object.entries(providerErrors).map(([key, value]) => `${key}: ${value}`),
      ].filter(Boolean).join('\n');

      this._showStatus({
        tone: 'info',
        icon: 'mdi:database-alert-outline',
        title: this._pt('partialTitle'),
        message: this._pt('partialBody'),
        details: detailsText,
        actions: [
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
        ],
      });
    }

    return false;
  }

  async _ensureMapLibre() {
    if (window.maplibregl) return;

    if (!document.querySelector('link[data-osm-parking-maplibre]')) {
      const css = document.createElement('link');
      css.rel = 'stylesheet';
      css.href = 'https://unpkg.com/maplibre-gl@5.6.2/dist/maplibre-gl.css';
      css.dataset.osmParkingMaplibre = '1';
      css.onerror = () => {
        css.onerror = null;
        css.href = 'https://cdn.jsdelivr.net/npm/maplibre-gl@5.6.2/dist/maplibre-gl.css';
      };
      document.head.appendChild(css);
    }

    if (!window.__osmParkingMapLibrePromise) {
      const sources = [
        'https://unpkg.com/maplibre-gl@5.6.2/dist/maplibre-gl.js',
        'https://cdn.jsdelivr.net/npm/maplibre-gl@5.6.2/dist/maplibre-gl.js',
      ];

      window.__osmParkingMapLibrePromise = (async () => {
        let lastError = null;
        for (const src of sources) {
          try {
            await new Promise((resolve, reject) => {
              const script = document.createElement('script');
              script.src = src;
              script.dataset.osmParkingMaplibre = '1';
              script.onload = resolve;
              script.onerror = () => {
                script.remove();
                reject(new Error(`Could not load MapLibre from ${src}`));
              };
              document.head.appendChild(script);
            });
            if (window.maplibregl) return;
          } catch (error) {
            lastError = error;
          }
        }
        throw lastError || new Error('Could not load MapLibre GL JS');
      })().catch((error) => {
        window.__osmParkingMapLibrePromise = null;
        throw error;
      });
    }

    await window.__osmParkingMapLibrePromise;
  }

  _translations() {
    const raw = String(this._hass?.language || 'en').replace('_', '-');
    if (OSM_PARKING_I18N[raw]) return OSM_PARKING_I18N[raw];
    const base = raw.split('-')[0];
    return OSM_PARKING_I18N[base] || OSM_PARKING_I18N.en;
  }

  _t(key) {
    return this._translations()[key] ?? OSM_PARKING_I18N.en[key] ?? key;
  }

  _n(value) {
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
  }

  _esc(value) {
    return String(value ?? '').replace(
      /[&<>'"]/g,
      char => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        "'": '&#39;',
        '"': '&quot;',
      }[char]),
    );
  }

  _displayPrice(suggestion) {
    if (!this.config.show_price) return '';
    if (suggestion.price) return String(suggestion.price);
    if (suggestion.charge) return String(suggestion.charge);
    if (suggestion.pricing?.charge) return String(suggestion.pricing.charge);
    if (String(suggestion.fee).toLowerCase() === 'no') return this._t('free');
    if (String(suggestion.fee).toLowerCase() === 'yes') return this._t('paid');
    return '';
  }

  _labelType(suggestion) {
    const category = suggestion.category;
    const categories = this._translations().categories || {};
    if (category && categories[category]) return categories[category];
    return suggestion.parking_type || this._t('parking');
  }

  _popupHtml(suggestion, index) {
    const price = this._displayPrice(suggestion);
    const distance = suggestion.distance_m != null
      ? `${Math.round(Number(suggestion.distance_m))} m`
      : '';
    const access = suggestion.access && suggestion.access !== 'unknown'
      ? suggestion.access
      : '';
    const availability = this._availabilityText(suggestion);
    const kind = suggestion.availability_kind || (suggestion.has_realtime_data ? 'live' : 'static');
    const availabilityLabel = kind === 'reported'
      ? this._qt('reported')
      : suggestion.availability_freshness === 'unverified'
        ? this._qt('liveUnverified') : this._pt('live');
    const estimatedOccupancy = this._estimatedOccupancyText(suggestion);
    const prediction = kind === 'predicted' && suggestion.predicted_occupancy_percent != null
      ? Number(suggestion.predicted_occupancy_percent) : NaN;
    const provider = suggestion.provider_name && suggestion.provider !== 'osm'
      ? String(suggestion.provider_name)
      : '';
    const updated = kind === 'live' ? this._formatProviderTime(suggestion.realtime_updated_at) : '';
    const checked = kind === 'reported' ? this._formatProviderTime(suggestion.availability_checked_at) : '';
    const sourceCount = Number(suggestion.deduplicated_source_count) || 0;

    const lines = [
      distance && `<div class="popup-line">${this._esc(this._t('distance'))}: ${this._esc(distance)}</div>`,
      `<div class="popup-line">${this._esc(this._t('type'))}: ${this._esc(this._labelType(suggestion))}</div>`,
      availability && `<div class="popup-line">${this._esc(availabilityLabel)}: ${this._esc(availability)}</div>`,
      Number.isFinite(prediction) && prediction >= 0 && prediction <= 100 && `<div class="popup-line">${this._esc(this._qt('predicted'))}: ${Math.round(prediction)}%</div>`,
      estimatedOccupancy && `<div class="popup-line">${this._esc(this._estimatedTranslations().label)}: ${this._esc(estimatedOccupancy)}</div>`,
      price && `<div class="popup-line">${this._esc(this._t('price'))}: ${this._esc(price)}</div>`,
      access && `<div class="popup-line">${this._esc(this._t('access'))}: ${this._esc(access)}</div>`,
      provider && `<div class="popup-line">${this._esc(this._pt('source'))}: ${this._esc(provider)}${sourceCount > 1 ? ` · ${sourceCount} ${this._esc(this._qt('sources'))}` : ''}</div>`,
      checked && `<div class="popup-line">${this._esc(this._qt('checked'))}: ${this._esc(checked)}</div>`,
      updated && `<div class="popup-line">${this._esc(this._pt('updated'))}: ${this._esc(updated)}</div>`,
    ].filter(Boolean).join('');

    const actions = [
      suggestion.navigation_url && `<a href="${this._esc(suggestion.navigation_url)}" target="_blank" rel="noopener">${this._esc(this._t('navigate'))}</a>`,
      suggestion.osm_url && `<a href="${this._esc(suggestion.osm_url)}" target="_blank" rel="noopener">OSM</a>`,
      suggestion.provider_url && `<a href="${this._esc(suggestion.provider_url)}" target="_blank" rel="noopener">${this._esc(this._pt('source'))}</a>`,
    ].filter(Boolean).join('');

    return `<div class="popup-title">${this._esc(suggestion.name || `${this._t('parking')} ${index + 1}`)}</div>${lines}${actions ? `<div class="popup-actions">${actions}</div>` : ''}`;
  }

  _clearMarkers() {
    for (const marker of this._markers) marker.remove();
    this._markers = [];
  }

  _updateZoneOverlay(zones) {
    if (!this._map?.isStyleLoaded()) return;
    const id = 'osm-parking-controlled-zones';
    const valid = (this.config.show_zones !== false ? zones : []).filter(zone =>
      zone?.type === 'Feature'
      && ['Polygon', 'MultiPolygon'].includes(zone?.geometry?.type)
      && zone?.properties?.record_type === 'zone',
    );
    const data = { type: 'FeatureCollection', features: valid };
    const source = this._map.getSource(id);
    if (source) {
      source.setData(data);
      return;
    }
    if (!valid.length) return;
    this._map.addSource(id, { type: 'geojson', data });
    this._map.addLayer({
      id: `${id}-fill`, type: 'fill', source: id,
      paint: { 'fill-color': '#d18c23', 'fill-opacity': 0.19 },
    });
    this._map.addLayer({
      id: `${id}-border`, type: 'line', source: id,
      paint: { 'line-color': '#bd7914', 'line-width': 2 },
    });
    this._map.on('click', `${id}-fill`, event => {
      const properties = event.features?.[0]?.properties;
      if (!properties) return;
      const name = this._esc(properties.name || this._zt('zone'));
      const sourceUrl = String(properties.provider_url || '');
      const link = sourceUrl.startsWith('https://')
        ? `<div class="popup-actions"><a href="${this._esc(sourceUrl)}" target="_blank" rel="noopener">${this._esc(this._pt('source'))}</a></div>`
        : '';
      new maplibregl.Popup({ offset: 12 })
        .setLngLat(event.lngLat)
        .setHTML(`<div class="popup-title">${name}</div><div class="popup-line">${this._esc(this._zt('signage'))}</div>${link}`)
        .addTo(this._map);
    });
    this._map.on('mouseenter', `${id}-fill`, () => {
      this._map.getCanvas().style.cursor = 'pointer';
    });
    this._map.on('mouseleave', `${id}-fill`, () => {
      this._map.getCanvas().style.cursor = '';
    });
  }

  async _update() {
    this._hideStatus();
    this._setContentVisible(true);

    const attributes = this._stateObj?.attributes || {};
    const destinationLat = this._n(attributes.destination_latitude);
    const destinationLon = this._n(attributes.destination_longitude);
    const destinationName =
      attributes.destination_name
      || attributes.destination_entity
      || this._t('destination');
    const suggestions = Array.isArray(attributes.suggestions)
      ? attributes.suggestions
      : [];
    const zones = Array.isArray(attributes.parking_zones) ? attributes.parking_zones : [];

    this._els.title.textContent = this.config.title || this._t('title');
    const subtitle = [];
    if (destinationName) subtitle.push(String(destinationName));
    if (suggestions.length) {
      subtitle.push(
        `${suggestions.length} ${this._t(suggestions.length === 1 ? 'suggestion' : 'suggestions')}`,
      );
    } else if (zones.length && this.config.show_zones !== false) {
      subtitle.push(`${zones.length} ${this._zt('zones')}`);
    } else if (this._stateObj?.state === 'waiting') {
      subtitle.push(this._t('waiting'));
    } else {
      subtitle.push(this._t('none'));
    }
    this._els.subtitle.textContent = subtitle.join(' · ');

    if (this._showBackendStatus(attributes)) {
      this._setContentVisible(false);
      return;
    }

    if (destinationLat == null || destinationLon == null) {
      this._setContentVisible(false);
      this._showStatus({
        tone: 'warning',
        icon: 'mdi:crosshairs-question',
        title: this._st('sourceCoordsTitle'),
        message: this._st('sourceCoordsBody'),
        details: attributes.error || this._t('coords'),
        actions: [
          ...(attributes.destination_entity ? [{
            label: this._st('openSource'),
            handler: () => this._openSource(attributes.destination_entity),
          }] : []),
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
          { label: this._st('settings'), handler: () => this._openSettings() },
        ],
      });
      return;
    }

    try {
      await this._ensureMapLibre();

      if (!this._map) {
        this._map = new maplibregl.Map({
          container: this._els.map,
          style: this.config.map_style,
          center: [destinationLon, destinationLat],
          zoom: 15,
          attributionControl: true,
        });
        this._map.addControl(
          new maplibregl.NavigationControl({ showCompass: false }),
          'top-right',
        );

        await new Promise((resolve, reject) => {
          if (this._map.loaded()) {
            resolve();
            return;
          }
          this._map.once('load', resolve);
          this._map.once(
            'error',
            event => reject(event?.error || new Error('Map failed to load')),
          );
        });
      }
    } catch (error) {
      try {
        this._map?.remove();
      } catch (_) {
        // Ignore cleanup errors from a partially initialized map.
      }
      this._map = null;
      this._setContentVisible(false);
      this._showStatus({
        tone: 'error',
        icon: 'mdi:map-marker-off-outline',
        title: this._st('mapTitle'),
        message: this._st('mapBody'),
        details: error?.message || String(error),
        actions: [
          { label: this._st('retryNow'), handler: () => void this._update() },
        ],
      });
      return;
    }

    this._updateZoneOverlay(zones);
    this._clearMarkers();
    const bounds = new maplibregl.LngLatBounds();

    if (this.config.show_destination !== false) {
      const element = document.createElement('div');
      element.className = 'osm-dest-marker';
      element.textContent = '★';

      const popup = new maplibregl.Popup({ offset: 18 }).setHTML(
        `<div class="popup-title">${this._esc(destinationName)}</div><div class="popup-line">${this._esc(this._t('destination'))}</div>`,
      );
      const marker = new maplibregl.Marker({ element })
        .setLngLat([destinationLon, destinationLat])
        .setPopup(popup)
        .addTo(this._map);
      this._markers.push(marker);
      bounds.extend([destinationLon, destinationLat]);
    }

    suggestions.forEach((suggestion, index) => {
      const lat = this._n(suggestion.latitude);
      const lon = this._n(suggestion.longitude);
      if (lat == null || lon == null) return;

      const element = document.createElement('div');
      element.className = 'osm-park-marker';
      element.textContent = String(index + 1);

      const popup = new maplibregl.Popup({ offset: 18 })
        .setHTML(this._popupHtml(suggestion, index));
      const marker = new maplibregl.Marker({ element })
        .setLngLat([lon, lat])
        .setPopup(popup)
        .addTo(this._map);
      marker._osmSuggestionIndex = index;
      this._markers.push(marker);
      bounds.extend([lon, lat]);
    });

    if (!bounds.isEmpty()) {
      const southWest = bounds.getSouthWest();
      const northEast = bounds.getNorthEast();
      if (
        southWest.lng === northEast.lng
        && southWest.lat === northEast.lat
      ) {
        this._map.jumpTo({
          center: [destinationLon, destinationLat],
          zoom: 16,
        });
      } else {
        this._map.fitBounds(bounds, {
          padding: 40,
          maxZoom: 17,
          duration: 0,
        });
      }
    }

    setTimeout(() => this._map?.resize(), 0);

    if (
      suggestions.length === 0
      && (zones.length === 0 || this.config.show_zones === false)
      && attributes.status === 'ok'
      && !attributes.error
    ) {
      this._showStatus({
        tone: 'info',
        icon: 'mdi:information-outline',
        title: this._st('noResultsTitle'),
        message: this._st('noResultsBody'),
        actions: [
          { label: this._st('settings'), handler: () => this._openSettings() },
          { label: this._st('retryNow'), handler: () => void this._retryNow() },
        ],
      });
    }

    this._renderList(suggestions);
  }

  _renderList(suggestions) {
    if (this.config.show_list === false) return;

    this._els.list.innerHTML = '';

    suggestions.forEach((suggestion, index) => {
      const row = document.createElement('div');
      row.className = 'parking-row';

      const price = this._displayPrice(suggestion);
      const distance = suggestion.distance_m != null
        ? `${Math.round(Number(suggestion.distance_m))} m`
        : '';
      const type = this._labelType(suggestion);
      const availability = this._availabilityText(suggestion);
      const kind = suggestion.availability_kind || (suggestion.has_realtime_data ? 'live' : 'static');
      const availabilityMeta = availability
        ? `${kind === 'reported' ? this._qt('reported') : this._pt('live')}: ${availability}`
        : '';
      const estimatedOccupancy = this._estimatedOccupancyText(suggestion);
      const estimatedMeta = estimatedOccupancy
        ? `${this._estimatedTranslations().label}: ${estimatedOccupancy}`
        : '';
      const provider = suggestion.provider_name && suggestion.provider !== 'osm'
        ? String(suggestion.provider_name)
        : '';

      row.innerHTML = `
        <div class="badge">${index + 1}</div>
        <div>
          <div class="row-title">${this._esc(suggestion.name || `${this._t('parking')} ${index + 1}`)}</div>
          <div class="row-meta">${this._esc([distance, type, availabilityMeta, estimatedMeta].filter(Boolean).join(' · '))}</div>
          ${provider ? `<div class="row-source">${this._esc(this._pt('source'))}: ${this._esc(provider)}</div>` : ''}
        </div>
        <div class="row-price">${this._esc(price)}</div>
      `;

      row.addEventListener('click', () => {
        const lat = this._n(suggestion.latitude);
        const lon = this._n(suggestion.longitude);
        if (lat == null || lon == null || !this._map) return;

        this._map.easeTo({
          center: [lon, lat],
          zoom: Math.max(this._map.getZoom(), 17),
          duration: 350,
        });
        const marker = this._markers.find(
          candidate => candidate._osmSuggestionIndex === index,
        );
        marker?.togglePopup();
        this._els.map.scrollIntoView({
          behavior: 'smooth',
          block: 'nearest',
        });
      });

      this._els.list.appendChild(row);
    });
  }
}

